window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-866fa1a614bdcd7c"]={"versions": [{"id": "FIG-866fa1a614bdcd7c", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild / Schichtenarchitektur der AUTOSAR Classic Platform Basissoftware (BSW). Das Diagramm stellt die hierarchische Einbettung und Abgrenzung des LIN-Kommunikationsstacks („LIN stack scope“) innerhalb der BSW-Schichten dar: Communication Services, Communication Hardware Abstraction, Communication Drivers sowie die unterlagerte Mikrocontroller-Hardware (µC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Module und Hardware-Entitäten nach Schichten:</p>\n<ul class=\"fig-list\"><li>Communication Services: AUTOSAR COM, DCM (Diagnostic Communication Manager), Communication Manager (ComM), PDU Router (PduR) sowie der grau hervorgehobene LIN State Manager (LinSM).\n</li><li>Communication Hardware Abstraction: LIN Interface (LinIf, grau hervorgehoben).\n</li><li>Communication Drivers: LIN Driver (Lin, grau hervorgehoben).\n</li><li>µC: Zwei Hardware-Einheiten des Serial Communication Interface (SCI).\n</li></ul>\n<p class=\"fig-p\">Grau hinterlegte Blöcke definieren den LIN-Stack-Scope. Es sind keine expliziten Port- oder Bus-Schnittstellenpfeile eingezeichnet; die Kopplung und Hierarchie ergibt sich implizit aus der Schichtenanordnung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablaufdynamik. Das Diagramm modelliert weder Kontroll- noch Datenflüsse, API-Aufrufe, Schedule-Umschaltungen noch Zustandsübergänge des LIN State Managers oder des Communication Managers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Schichtenzugehörigkeit und des Modulumfangs des LIN-Stacks (LinSM, LinIf, LIN Driver) im AUTOSAR-Gesamtkontext. Das Diagramm dient als architektonische Übersicht zur Abgrenzung generischer Kommunikationsbausteine von busspezifischen Modulen; Hardware-Transceiver-Treiber (LinTrcv) und detaillierte Interaktionsschnittstellen sind hier abstrahiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d9c75ac78306a416", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild / Schichtenarchitektur der AUTOSAR Classic Platform Basissoftware (BSW). Das Diagramm stellt die hierarchische Einbettung und Abgrenzung des LIN-Kommunikationsstacks („LIN stack scope“) innerhalb der BSW-Schichten dar: Communication Services, Communication Hardware Abstraction, Communication Drivers sowie die unterlagerte Mikrocontroller-Hardware (µC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Module und Hardware-Entitäten nach Schichten:</p>\n<ul class=\"fig-list\"><li>Communication Services: AUTOSAR COM, DCM (Diagnostic Communication Manager), Communication Manager (ComM), PDU Router (PduR) sowie der grau hervorgehobene LIN State Manager (LinSM).\n</li><li>Communication Hardware Abstraction: LIN Interface (LinIf, grau hervorgehoben).\n</li><li>Communication Drivers: LIN Driver (Lin, grau hervorgehoben).\n</li><li>µC: Zwei Hardware-Einheiten des Serial Communication Interface (SCI).\n</li></ul>\n<p class=\"fig-p\">Grau hinterlegte Blöcke definieren den LIN-Stack-Scope. Es sind keine expliziten Port- oder Bus-Schnittstellenpfeile eingezeichnet; die Kopplung und Hierarchie ergibt sich implizit aus der Schichtenanordnung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablaufdynamik. Das Diagramm modelliert weder Kontroll- noch Datenflüsse, API-Aufrufe, Schedule-Umschaltungen noch Zustandsübergänge des LIN State Managers oder des Communication Managers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung der Schichtenzugehörigkeit und des Modulumfangs des LIN-Stacks (LinSM, LinIf, LIN Driver) im AUTOSAR-Gesamtkontext. Das Diagramm dient als architektonische Übersicht zur Abgrenzung generischer Kommunikationsbausteine von busspezifischen Modulen; Hardware-Transceiver-Treiber (LinTrcv) und detaillierte Interaktionsschnittstellen sind hier abstrahiert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-866fa1a614bdcd7c", "to": "FIG-d9c75ac78306a416", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Block DCM: Beschriftung korrigiert von „Diagnos tic Com. Manage“ zu „Diagnostic Com. Manager“.\n</li><li>Block LIN Driver: Vertikale Textbeschneidung am unteren Rand behoben („LIN Driver“ ist nun vollständig lesbar).\n</li></ul>"}]};
